CREATE TABLE export_log(export_log_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,module VARCHAR(50) NOT NULL,filter_condition TEXT,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',file_name VARCHAR(255),file_url VARCHAR(500),row_count INT,fail_reason VARCHAR(500),expired_at DATETIME,operator_id BIGINT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_export_farm_status(farm_id,status),INDEX idx_export_operator(farm_id,operator_id),INDEX idx_export_expiry(expired_at));
